INSERT INTO `catalogo_producto` (`id`, `nombre`, `descripcion`, `precio`, `activo`, `en_oferta`, `porcentaje_descuento`, `creado`, `actualizado`, `categoria_id`, `subcategoria_id`, `temporada`) VALUES (11,'Bikini','Bikini de marca europea, muy clásico para cualquier día soleado.',40.00,1,1,10,'2026-08-02 12:56:07.647880','2026-08-02 15:21:17.795553',1,3,'verano'),(13,'Tanga','Diseñada para ofrecer un ajuste discreto y una sensación de libertad incomparable.',20.00,1,1,5,'2026-08-02 13:11:09.208001','2026-08-03 03:34:02.837158',1,2,'todo_el_anio'),(14,'Tanga','Siéntete segura con un diseño moderno y delicado.',24.00,1,0,0,'2026-08-02 13:13:29.996015','2026-08-02 15:31:57.305676',1,2,'todo_el_anio'),(15,'Hilo Dental','Ideal para lucir tus prendas favoritas sin marcas visibles.',15.00,1,1,2,'2026-08-02 13:18:36.115539','2026-08-02 15:33:20.027230',1,2,'todo_el_anio'),(16,'Hilo Dental','Comodidad y estilo en una prenda casi imperceptible.',10.00,1,0,0,'2026-08-02 13:19:56.149626','2026-08-02 15:34:13.899123',1,2,'todo_el_anio'),(17,'Culotte','Cobertura completa sin renunciar al estilo.',20.00,1,1,10,'2026-08-02 13:21:09.767876','2026-08-02 15:35:26.618360',1,2,'todo_el_anio'),(18,'Culotte','Ideal para disfrutar de una sensación de comodidad durante todo el día.',20.00,1,0,0,'2026-08-02 13:22:37.436990','2026-08-03 05:01:15.239079',1,2,'todo_el_anio'),(19,'Boyshort','Inspirado en el confort deportivo con un toque femenino.',35.00,1,0,0,'2026-08-02 13:25:14.661133','2026-08-24 02:50:11.950104',1,2,'todo_el_anio'),(20,'Bóxer ajustado (Boxer Brief)','Diseñado para ofrecer soporte y comodidad en todo momento.',35.00,1,0,0,'2026-08-02 13:27:26.042646','2026-08-24 02:49:14.085862',2,5,'todo_el_anio'),(21,'Bóxer ajustado (Boxer Brief)','Ajuste firme que acompaña cada uno de tus movimientos.',20.00,1,0,0,'2026-08-02 13:29:55.911317','2026-08-02 15:40:25.407287',2,5,'todo_el_anio'),(22,'Bóxer suelto','Frescura y comodidad para quienes prefieren un ajuste relajado.',20.00,1,1,2,'2026-08-02 13:32:34.051265','2026-08-23 22:21:19.140774',2,5,'todo_el_anio'),(23,'Bóxer suelto','El compañero perfecto para descansar o usar a diario.',20.00,1,0,0,'2026-08-02 13:35:03.024891','2026-08-02 15:41:49.084961',2,5,'todo_el_anio'),(24,'Slip','Un clásico que nunca pasa de moda por su excelente ajuste.',25.00,1,1,5,'2026-08-02 13:53:41.160930','2026-08-02 15:42:29.972338',2,5,'todo_el_anio'),(25,'Slip','Soporte y confort en un diseño práctico y funcional.',25.00,1,0,0,'2026-08-02 13:55:13.640831','2026-08-02 15:43:36.236915',2,5,'todo_el_anio'),(26,'Brief','La elección ideal para quienes buscan soporte y libertad de movimiento.',26.00,1,0,0,'2026-08-02 13:59:11.539814','2026-08-02 15:45:35.834787',2,5,'todo_el_anio'),(27,'Bikini','Bikini Prueba',20.00,1,0,0,'2026-08-03 04:50:29.682136','2026-08-03 04:50:29.682165',1,3,'verano'),(29,'Corpiño','Corpiño básico con tiras regulables, cómodo y de buen soporte.',35.00,1,0,0,'2026-08-23 19:02:56.575345','2026-08-23 19:05:35.112472',1,2,'todo_el_anio'),(32,'Corpiño sin armado','Corpiño cómodo, sin relleno ni aro.',25.00,1,0,0,'2026-08-23 20:20:03.716189','2026-08-23 20:20:03.716286',1,1,'todo_el_anio'),(33,'Fajas','Hermosas fajas para amoldar tu cuerpo',25.00,1,0,0,'2026-08-23 20:26:16.403362','2026-08-23 20:26:16.403530',1,2,'todo_el_anio'),(34,'Colalé','De buena calidad y durabilidad',10.00,1,0,0,'2026-08-23 20:31:45.706186','2026-08-24 01:41:00.361540',1,2,'todo_el_anio'),(35,'Bóxer infantil','Cómo y suave',15.00,1,0,0,'2026-08-23 20:36:47.981288','2026-08-23 20:36:47.981461',2,5,'todo_el_anio'),(36,'Medias','Medias nuevas, cómodas y suaves, ideales para el uso diario. Diseñadas para brindar un ajuste agradable y complementar cualquier estilo.',10.00,1,0,0,'2026-08-23 20:41:39.043908','2026-11-18 13:03:58.415218',9,19,'todo_el_anio'),(37,'Top clásico','Clásico para cualquier día relajado',25.00,1,0,0,'2026-08-23 20:47:01.638924','2026-08-23 20:47:01.639253',1,1,'todo_el_anio'),(38,'Bandeau top sin tiros','top tipo bandeau, sin tiras, sencillo y cómodo.',20.00,1,0,0,'2026-08-23 20:50:32.155931','2026-08-23 20:50:32.156031',1,1,'todo_el_anio'),(39,'Calzocillo de niño','Suaves y ligeros',10.00,1,0,0,'2026-08-23 20:56:12.547759','2026-08-23 20:56:12.547845',2,5,'todo_el_anio'),(42,'Tirantes','¿Necesitas extenciones para el sostén?, no lo pienses más',10.00,1,0,0,'2026-08-23 21:34:00.985425','2026-08-23 21:34:39.110693',1,1,'todo_el_anio'),(43,'Calzón faja','Mejor calidad',25.00,1,0,0,'2026-08-23 21:38:55.972323','2026-08-23 21:38:55.972485',1,2,'todo_el_anio'),(44,'Cubre pezón','Cómodos y resistentes',35.00,1,0,0,'2026-08-23 21:41:47.665996','2026-08-23 21:41:47.666061',1,1,'todo_el_anio'),(45,'Medias Antideslizantes','medias con puntos antideslizantes en la planta.',20.00,1,0,0,'2026-08-23 21:44:02.441227','2026-08-23 21:44:02.441304',9,19,'todo_el_anio'),(46,'Medias infantiles','Medias suaves y cómodas para niños.',15.00,1,0,0,'2026-08-23 21:47:01.299944','2026-08-23 21:47:01.300035',9,19,'todo_el_anio'),(47,'Pañuelos','Prácticos y bellos',10.00,1,0,0,'2026-08-23 22:20:26.697501','2026-08-23 22:20:26.697571',9,20,'todo_el_anio'),(48,'Calzón clasico','Comodidas en todo momento',15.00,1,0,0,'2026-08-24 02:54:46.221694','2026-08-24 02:55:12.836017',1,2,'todo_el_anio'),(49,'Traje de baño usado','Trajes de baño usados en buen estado, cómodos y funcionales, ideales para quienes buscan una opción económica. Se venden limpios y listos para darles una segunda oportunidad.',20.00,1,0,0,'2026-11-18 10:32:20.095713','2026-11-18 12:43:12.832522',1,3,'verano'),(50,'Maya usada','Malla usada en buen estado, cómoda y práctica, ideal para disfrutar de actividades acuáticas. Una opción económica y lista para darle una segunda oportunidad.',20.00,1,0,0,'2026-11-18 12:39:44.856457','2026-11-18 12:41:02.579704',1,3,'verano'),(51,'Biquini usado','Bikini usado en buen estado, cómodo y práctico, ideal para disfrutar de la piscina o la playa. Una opción económica, lista para darle una segunda oportunidad.',20.00,1,0,0,'2026-11-18 12:47:03.266891','2026-11-18 12:47:03.266921',1,3,'verano'),(52,'Cachetero Liso','Cachetero nuevo, cómodo y suave, diseñado para brindar un ajuste agradable y libertad de movimiento. Ideal para el uso diario.',15.00,1,0,0,'2026-11-18 12:52:49.629563','2026-11-18 12:57:21.659520',1,2,'todo_el_anio'),(53,'Cachetero con diseño','Cachetero nuevo con diseño moderno y atractivo, confeccionado para brindar comodidad y un ajuste perfecto. Ideal para quienes buscan combinar estilo y confort en su día a día.',20.00,1,0,0,'2026-11-18 12:56:46.015781','2026-11-18 12:56:46.015810',1,2,'todo_el_anio'),(54,'Medias de marca','Medias de marca, de excelente calidad, cómodas y resistentes. Ideales para el uso diario, combinando estilo, durabilidad y confort.',15.00,1,0,0,'2026-11-18 13:02:42.259704','2026-11-18 13:02:42.259736',9,19,'todo_el_anio'),(55,'Ropa usada','Ropa usada de mujer en buen estado, variedad de blusas y jeans de diferentes estilos y diseños. Prendas cómodas, bonitas y a precios accesibles para renovar tu guardarropa.',20.00,1,0,0,'2026-11-18 13:11:20.042400','2026-11-18 13:11:20.042463',1,27,'todo_el_anio'),(56,'Ropa usada','Ropa usada de hombre en buen estado, variedad de camisas, poleras, pantalones y jeans de diferentes estilos. Prendas cómodas y versátiles a precios accesibles para renovar tu guardarropa.',20.00,1,0,0,'2026-11-18 13:16:43.629358','2026-11-18 13:16:43.629388',2,26,'todo_el_anio');
